{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/lab",
  "data": {
    "name": "CircleCheckIndicator",
    "displayName": "Circle Check Indicator",
    "category": "Form Controls",
    "keywords": [
      "indicator",
      "checkbox",
      "circle",
      "check",
      "multiselect",
      "selection",
      "edit mode",
      "ios",
      "mark"
    ],
    "description": "The iOS multiple-selection mark: an empty circle, a filled circle with a checkmark, or a filled circle with a bar for the partial state. A checkbox-family indicator: map it to `checkbox` with defineTheme({indicators}) and every CheckboxInput and CheckboxList draws it. Decorative (aria-hidden); the owning control keeps the input, role, accessible name, focus, and keyboard behavior. Its colors fade over the theme duration on every pointer and change at once under Reduce Motion.",
    "props": [
      {
        "name": "state",
        "type": "'unchecked' | 'checked' | 'indeterminate'",
        "description": "Which state to draw. The unchecked circle is an empty ring, not nothing.",
        "required": true
      },
      {
        "name": "size",
        "type": "'sm' | 'md'",
        "description": "Control size. The circle draws at UIKit’s diameters, 18px (sm) or 21.8px (md), centred in the host’s 20px or 24px slot.",
        "default": "'md'"
      },
      {
        "name": "isDisabled",
        "type": "boolean",
        "description": "Draws the disabled look. Purely visual; the owning control keeps the disabled semantics.",
        "default": "false"
      },
      {
        "name": "children",
        "type": "ReactNode",
        "description": "Content drawn inside the circle instead of the mark, e.g. the loading Spinner CheckboxInput passes while a change is pending."
      },
      {
        "name": "xstyle",
        "type": "StyleXStyles",
        "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value, not an inline style object like style={{}}."
      }
    ],
    "theming": {
      "targets": [
        {
          "className": "astryx-circle-check-indicator",
          "visualProps": [
            "size",
            "checked",
            "disabled"
          ]
        },
        {
          "className": "astryx-circle-check-indicator-check",
          "visualProps": [
            "size"
          ]
        },
        {
          "className": "astryx-circle-check-indicator-dash",
          "visualProps": [
            "size"
          ]
        }
      ]
    },
    "usage": {
      "description": "Use it where iOS shows a selection circle: the rows of a list in edit mode, and multiple-choice sets whose product follows iOS. Map it to `checkbox` in a theme to change every checkbox at once, or render it in a row you lay out yourself.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Map it with defineTheme({indicators: {checkbox: CircleCheckIndicator}}) so CheckboxInput and CheckboxList keep their semantics and focus ring."
        },
        {
          "guidance": true,
          "description": "Map it only in a theme meant for iOS. It draws the circle on every platform, and Android marks multiple choice with a square box."
        },
        {
          "guidance": true,
          "description": "Keep a visible label beside it; the circle is decorative and announces nothing."
        },
        {
          "guidance": false,
          "description": "Use it for a single choice; a radio, or a checkmark on the chosen row, says \"one of these\"."
        },
        {
          "guidance": false,
          "description": "Give it a role, a label or a tab stop; the owning control has those."
        }
      ]
    },
    "package": "@astryxdesign/lab",
    "import": "@astryxdesign/lab",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
